    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> path,
    required int kind,
  }) => $allocator<FffWatchEvent>()
    ..ref.path = path
    ..ref.kind = kind;
}

/// A batch of watch events. Free with `fff_free_watch_events`.
/// Versioned by append only: existing field offsets never move.
final class FffWatchEventBatch extends ffi.Struct {
  external ffi.Pointer<FffWatchEvent> events;

  @ffi.Uint32()
