  /// Parallel to `events`, `count` long: the pre-rename path for entries
  /// with `kind == 4`, null for every other entry. Null when the batch holds
  /// no renames at all.
  external ffi.Pointer<ffi.Pointer<ffi.Char>> rename_sources;

  static ffi.Pointer<FffWatchEventBatch> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<FffWatchEvent> events,
    required int count,
    required ffi.Pointer<ffi.Pointer<ffi.Char>> rename_sources,
  }) => $allocator<FffWatchEventBatch>()
    ..ref.events = events
    ..ref.count = count
    ..ref.rename_sources = rename_sources;
}

